function receipt(items, locale, currency) {
  const money = new Intl.NumberFormat(locale, { style: "currency", currency });
  const lines = [];
  let total = 0;
  let count = 0;
  for (const { name, cents, qty } of items) {
    const lineCents = qty * cents;
    total += lineCents;
    count += qty;
    lines.push(`${qty} × ${name}: ${money.format(lineCents / 100)}`);
  }
  lines.push(`Total: ${money.format(total / 100)}`);
  if (items.length) {
    const names = new Intl.ListFormat(locale, { type: "conjunction" }).format(items.map(i => i.name));
    const word = new Intl.PluralRules("en").select(count) === "one" ? "item" : "items";
    lines.push(`${names} — ${count} ${word}`);
  }
  return lines.join("\n");
}

unitTests:
test("US dollars", () => {
  const text = receipt([{ name: "Tea", cents: 250, qty: 2 }, { name: "Cake", cents: 375, qty: 1 }], "en-US", "USD");
  checkEq(text, "2 × Tea: $5.00\n1 × Cake: $3.75\nTotal: $8.75\nTea and Cake — 3 items");
});

test("one item, and lists of three", () => {
  checkEq(receipt([{ name: "Jam", cents: 199, qty: 1 }], "en-US", "USD"), "1 × Jam: $1.99\nTotal: $1.99\nJam — 1 item");
  const three = receipt([{ name: "A", cents: 100, qty: 1 }, { name: "B", cents: 100, qty: 1 }, { name: "C", cents: 100, qty: 1 }], "en-US", "USD");
  check(three.endsWith("A, B, and C — 3 items"), three);
});

test("other locales and empty", () => {
  const de = receipt([{ name: "Brot", cents: 350, qty: 1 }], "de-DE", "EUR");
  const expected = new Intl.NumberFormat("de-DE", { style: "currency", currency: "EUR" }).format(3.5);
  check(de.startsWith(`1 × Brot: ${expected}`), de);
  checkEq(receipt([], "en-US", "USD"), "Total: $0.00");
});

